BASELINE_FILENAME = "openphoto_calibrated_baseline.json"
DEFAULT_APP_PACKAGE = "com.killt.openphotoedit"
DEFAULT_EXPORT_DIR = "/sdcard/Pictures/OpenPhotoEdit"


def _shell_quote(value: str) -> str:
    return shlex.quote(str(value))


def _list_exports(controller: Any, export_dir: str) -> list[dict[str, Any]]:
    quoted_dir = _shell_quote(export_dir)
    command = (
        f"if [ -d {quoted_dir} ]; then "
        f"for f in {quoted_dir}/OpenPhotoEdit_*.jpg; do "
        "[ -f \"$f\" ] || continue; "
        "size=$(wc -c < \"$f\" 2>/dev/null || echo 0); "
        "mtime=$(stat -c %Y \"$f\" 2>/dev/null || stat -f %m \"$f\" 2>/dev/null || echo 0); "
        "printf '%s\t%s\t%s\n' \"$f\" \"$size\" \"$mtime\"; "
        "done; "
        "fi"
    )
    output = str(controller.execute_adb(["shell", command]) or "")
    entries: list[dict[str, Any]] = []
    for line in output.splitlines():
        parts = line.rstrip("\n").split("\t")
        if len(parts) != 3:
            continue
        path, size_raw, mtime_raw = parts
        try:
            size = int(str(size_raw).strip() or "0")
        except ValueError:
            size = 0
        try:
            mtime = int(str(mtime_raw).strip() or "0")
        except ValueError:
            mtime = 0
        entries.append({"path": path, "size": size, "mtime": mtime})
    entries.sort(key=lambda item: (int(item.get("mtime") or 0), str(item.get("path") or "")))
    return entries


def _load_baseline(run_dir: str | None) -> dict[str, Any] | None:
    if not run_dir:
        return None
    path = Path(run_dir) / BASELINE_FILENAME
    if not path.is_file():
        return None
    return json.loads(path.read_text(encoding="utf-8"))


def _node_text(node: Mapping[str, Any]) -> str:
    return str(
        node.get("text")
        or node.get("content_desc")
        or node.get("content-desc")
        or node.get("contentDescription")
        or ""
    )


def _collect_ui_evidence(observation: Any, app_package: str) -> dict[str, Any]:
    texts: list[str] = []
    packages: list[str] = []
    if observation is not None:
        for node in getattr(observation, "ui_nodes", []) or []:
            if not isinstance(node, Mapping):
                continue
            text = _node_text(node).strip()
            if text:
                texts.append(text)
            package = str(node.get("package") or "").strip()
            if package:
                packages.append(package)
    unique_texts = list(dict.fromkeys(texts))
    unique_packages = list(dict.fromkeys(packages))
    anchors = [
        anchor
        for anchor in ("Export", "Undo", "Redo", "Edit", "Exposure", "Filters", "Landscape", "HSL")
        if anchor in unique_texts
    ]
    foreground_bundle = str(getattr(observation, "foreground_bundle_id", "") or "")
    foreground_app = str(getattr(observation, "foreground_app", "") or "")
    foreground_window = str(getattr(observation, "foreground_window", "") or "")
    foreground_ok = (
        app_package in foreground_bundle
        or app_package in foreground_app
        or app_package in foreground_window
        or app_package in unique_packages
    )
    return {
        "foreground_bundle_id": foreground_bundle or None,
        "foreground_app": foreground_app or None,
        "foreground_window": foreground_window or None,
        "observed_node_packages": unique_packages[:20],
        "visible_texts": unique_texts[:100],
        "visible_anchors": anchors,
        "foreground_ok": foreground_ok,
        "final_editor_visible": bool(foreground_ok and len(set(anchors) & {"Export", "Edit", "Filters", "Landscape", "HSL"}) >= 2),
    }


def _trajectory_evidence(context: Mapping[str, Any], min_agent_steps: int) -> dict[str, Any]:
    run_dir = context.get("run_dir")
    path = Path(str(run_dir)) / "trajectory.jsonl" if run_dir else None
    if not path or not path.is_file():
        required = bool(run_dir and min_agent_steps > 0)
        return {
            "available": False,
            "path": str(path) if path else None,
            "agent_step_count": None,
            "min_agent_steps": min_agent_steps,
            "min_agent_steps_required": required,
            "min_agent_steps_met": not required,
        }
    count = 0
    parse_errors: list[str] = []
    with path.open("r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            try:
                json.loads(line)
                count += 1
            except json.JSONDecodeError as exc:
                parse_errors.append(str(exc))
    return {
        "available": True,
        "path": str(path),
        "agent_step_count": count,
        "min_agent_steps": min_agent_steps,
        "min_agent_steps_required": min_agent_steps > 0,
        "min_agent_steps_met": count >= min_agent_steps,
        "parse_errors": parse_errors[:5],
    }


def _median_rgb(image: Image.Image, box: list[int] | tuple[int, int, int, int]) -> list[int]:
    crop = image.crop(tuple(int(v) for v in box))
    pixels = list(crop.getdata())
    return [int(statistics.median(pixel[channel] for pixel in pixels)) for channel in range(3)]


def _max_delta(actual: Mapping[str, list[int]], expected: Mapping[str, list[int]]) -> int:
    deltas: list[int] = []
    for stripe, expected_rgb in expected.items():
        actual_rgb = actual.get(stripe) or [999, 999, 999]
        deltas.extend(abs(int(actual_rgb[i]) - int(expected_rgb[i])) for i in range(3))
    return max(deltas) if deltas else 999


class OpenPhotoCoastalCalibrationEvaluator(BaseEvaluator):
    """Verify two OpenPhotoEdit exports by RGB calibration-block pixel evidence."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        params = dict(context.get("params") or {})
        if controller is None or not hasattr(controller, "execute_adb"):
            return EvalResult(status=EvalStatus.ERROR, message="controller.execute_adb is required")

        app_package = str(params.get("app_package") or DEFAULT_APP_PACKAGE).strip()
        export_dir = str(params.get("export_dir") or DEFAULT_EXPORT_DIR).strip()
        min_file_size_bytes = int(params.get("min_file_size_bytes", 100000) or 0)
        min_agent_steps = int(params.get("min_agent_steps", 0) or 0)  # reported, not required
        tolerance = int(params.get("channel_tolerance", 12) or 0)
        expected_dimensions = [int(v) for v in (params.get("expected_dimensions") or [1280, 800])]
        sample_boxes = params.get("sample_boxes") or {}
        profiles = params.get("profiles") or []
        require_baseline_for_run_dir = bool(params.get("require_baseline_for_run_dir", True))
        # Optional: bind each profile to the photo it must be exported from.  The
        # calibration patches are identical in a task's two inputs, so the stripe
        # medians alone accept the right recipe applied to the wrong photo.
        source_binding = params.get("source_binding") if isinstance(params.get("source_binding"), Mapping) else None
        fixture_key = str((source_binding or {}).get("fixture_key") or "")
        min_source_correlation = float(
            (source_binding or {}).get("min_correlation", calibration.DEFAULT_MIN_SOURCE_CORRELATION)
        )
        if source_binding is not None:
            try:
                calibration.source_thumbnails(fixture_key)
            except Exception as exc:
                return EvalResult(
                    status=EvalStatus.ERROR,
                    message=f"source-binding references are unavailable: {type(exc).__name__}: {exc}",
                    metadata={"exception_type": type(exc).__name__, "source_binding": dict(source_binding)},
                )

        if not sample_boxes or not isinstance(sample_boxes, Mapping):
            return EvalResult(status=EvalStatus.ERROR, message="sample_boxes must be provided")
        if not isinstance(profiles, list) or len(profiles) < 2:
            return EvalResult(status=EvalStatus.ERROR, message="at least two calibration profiles are required")

        try:
            current_entries = _list_exports(controller, export_dir)
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Failed to list OpenPhotoEdit exports: {type(exc).__name__}: {exc}",
                metadata={"exception_type": type(exc).__name__, "export_dir": export_dir},
            )

        run_dir = context.get("run_dir")
        baseline = _load_baseline(str(run_dir)) if run_dir else None
        baseline_paths = set(str(path) for path in (baseline or {}).get("paths", []) if str(path))
        baseline_required_but_missing = bool(run_dir and require_baseline_for_run_dir and baseline is None)

        valid_entries = [
            entry
            for entry in current_entries
            if int(entry.get("size") or 0) >= min_file_size_bytes
            and str(entry.get("path") or "").lower().endswith(".jpg")
        ]
        candidate_entries = (
            [entry for entry in valid_entries if str(entry.get("path") or "") not in baseline_paths]
            if baseline is not None
            else valid_entries
        )

        file_evidence: list[dict[str, Any]] = []
        with tempfile.TemporaryDirectory(prefix="openphoto-calibrated-") as tmpdir:
            tmp_path = Path(tmpdir)
            for index, entry in enumerate(candidate_entries):
                remote_path = str(entry.get("path") or "")
                local_path = tmp_path / f"candidate_{index}.jpg"
                pulled = str(controller.execute_adb(["pull", remote_path, str(local_path)]) or "")
                evidence: dict[str, Any] = {
                    "remote_path": remote_path,
                    "size": int(entry.get("size") or 0),
                    "mtime": int(entry.get("mtime") or 0),
                    "pull_output": pulled.strip(),
                    "local_pull_exists": local_path.is_file(),
                }
                try:
                    with Image.open(local_path) as raw:
                        image = raw.convert("RGB")
                        evidence["dimensions"] = [image.width, image.height]
                        sample_rgb = {
                            str(stripe): _median_rgb(image, box)
                            for stripe, box in sample_boxes.items()
                        }
                        evidence["sample_median_rgb"] = sample_rgb
                        evidence["dimension_ok"] = [image.width, image.height] == expected_dimensions
                        correlations = calibration.source_correlations(image, fixture_key) if source_binding is not None else None
                        best_source = max(correlations, key=correlations.get) if correlations else None
                        if correlations is not None:
                            evidence["source_correlations"] = correlations
                            evidence["best_matching_source_profile"] = best_source
                        profile_scores = []
                        for profile in profiles:
                            expected_rgb = profile.get("expected_median_rgb") if isinstance(profile, Mapping) else None
                            if not isinstance(expected_rgb, Mapping):
                                continue
                            max_delta = _max_delta(sample_rgb, expected_rgb)
                            profile_id = str(profile.get("profile_id") or "")
                            source_correlation = correlations.get(profile_id) if correlations is not None else None
                            source_bound = correlations is None or (
                                source_correlation is not None
                                and source_correlation >= min_source_correlation
                                and profile_id == best_source
                            )
                            profile_scores.append(
                                {
                                    "profile_id": str(profile.get("profile_id") or ""),
                                    "role": str(profile.get("role") or ""),
                                    "source_file": str(profile.get("source_file") or ""),
                                    "expected_median_rgb": dict(expected_rgb),
                                    "max_channel_delta": max_delta,
                                    "source_correlation": source_correlation,
                                    "source_bound": bool(source_bound),
                                    "within_tolerance": bool(
                                        max_delta <= tolerance and evidence["dimension_ok"] and source_bound
                                    ),
                                }
                            )
                        evidence["profile_scores"] = profile_scores
                except Exception as exc:
                    evidence["image_error"] = f"{type(exc).__name__}: {exc}"
                file_evidence.append(evidence)

        matched_profiles: dict[str, dict[str, Any]] = {}
        used_files: set[str] = set()
        for profile in profiles:
            profile_id = str(profile.get("profile_id") or "")
            best: dict[str, Any] | None = None
            for evidence in file_evidence:
                remote_path = str(evidence.get("remote_path") or "")
                if remote_path in used_files:
                    continue
                for score in evidence.get("profile_scores") or []:
                    if score.get("profile_id") != profile_id:
                        continue
                    candidate = {"remote_path": remote_path, "score": score, "sample_median_rgb": evidence.get("sample_median_rgb")}
                    score_delta = score.get("max_channel_delta")
                    best_delta = best["score"].get("max_channel_delta") if best is not None else None
                    # A file that satisfies the profile always beats one that does not.
                    score_key = (not bool(score.get("within_tolerance")), int(score_delta if score_delta is not None else 999))
                    best_key = (
                        (not bool(best["score"].get("within_tolerance")), int(best_delta if best_delta is not None else 999))
                        if best is not None
                        else None
                    )
                    if best_key is None or score_key < best_key:
                        best = candidate
            if best and bool(best["score"].get("within_tolerance")):
                matched_profiles[profile_id] = best
                used_files.add(str(best.get("remote_path") or ""))

        final_observation = context.get("final_observation")
        if final_observation is None:
            try:
                final_observation = controller.observe(include_ui_tree=True, include_screenshot_data=False)
            except Exception:
                final_observation = None
        ui_evidence = _collect_ui_evidence(final_observation, app_package)
        trajectory = _trajectory_evidence(context, min_agent_steps)

        expected_profile_ids = [str(profile.get("profile_id") or "") for profile in profiles]
        checks = {
            "baseline_available_or_not_required": not baseline_required_but_missing,
            "candidate_export_count_at_least_2": len(candidate_entries) >= 2,
            "all_expected_profiles_matched": all(profile_id in matched_profiles for profile_id in expected_profile_ids),
            "distinct_files_for_profiles": len({item.get("remote_path") for item in matched_profiles.values()}) >= len(expected_profile_ids),
            "final_editor_visible": bool(ui_evidence.get("final_editor_visible")),
        }
        failures = [name for name, passed in checks.items() if not passed]
        metadata = {
            "app_package": app_package,
            "export_dir": export_dir,
            "min_file_size_bytes": min_file_size_bytes,
            "channel_tolerance": tolerance,
            "expected_dimensions": expected_dimensions,
            "sample_boxes": dict(sample_boxes),
            "source_binding": (
                {"fixture_key": fixture_key, "min_correlation": min_source_correlation}
                if source_binding is not None
                else None
            ),
            "baseline_available": baseline is not None,
            "baseline_count": len((baseline or {}).get("entries", [])),
            "current_valid_export_count": len(valid_entries),
            "candidate_export_count": len(candidate_entries),
            "candidate_exports": candidate_entries,
            "file_evidence": file_evidence,
            "matched_profiles": matched_profiles,
            "checks": checks,
            "failures": failures,
            "ui_evidence": ui_evidence,
            "trajectory": trajectory,
            "evidence_note": (
                "Pixel evidence uses median RGB from central regions of the source-image calibration stripes. "
                "It rejects pre-existing exports through the initializer baseline during full runs."
            ),
        }
        if not failures:
            return EvalResult(
                status=EvalStatus.PASS,
                message="OpenPhotoEdit coastal exports match both calibrated RGB profiles and final editor evidence",
                metadata=metadata,
            )
        return EvalResult(
            status=EvalStatus.FAIL,
            message="OpenPhotoEdit calibrated export evidence is incomplete",
            metadata=metadata,
        )
